from pathlib import Path
from urllib.request import urlopen
from urllib.parse import unquote
import subprocess,re,html,json,hashlib,tempfile
R=Path(__file__).resolve().parents[1];page='https://opengameart.org/content/the-free-firearm-sound-library';s=urlopen(page,timeout=30).read().decode();links=[html.unescape(x) for x in re.findall(r'href=[\"\']([^\"\']+)',s) if '/sites/default/files/' in x and '.7z' in x];assert len(links)==1
url=links[0];print('Downloading official CC0 archive into memory; no archive file saved',flush=True);data=urlopen(url,timeout=90).read();archive=tempfile.TemporaryFile(dir=R/'records');archive.write(data);archive.seek(0); proc=subprocess.run(['bsdtar','-t','-f',f'/dev/fd/{archive.fileno()}'],pass_fds=(archive.fileno(),),capture_output=True);print(proc.stderr.decode()[:1200],flush=True);proc.check_returncode();names=proc.stdout.decode().splitlines();(R/'records/firearm_archive_paths.json').write_text(json.dumps(names,ensure_ascii=False,indent=2));print('Archive sample paths:',names[:25],flush=True);matches=[n for n in names if n.lower().endswith(('.wav','.ogg','.mp3','.flac')) and re.search(r'Ruger Single Six|Smith & Wesson 642',n,re.I)];print('Matched sample paths:',matches[:25],flush=True)
selected=matches[:24]+[n for n in names if n.endswith("Prepared Master Sheet.csv")];assert selected,'No suitable firearm sample paths; inspect saved archive index'
assert all(not Path(p).is_absolute() and '..' not in Path(p).parts for p in selected)
out=R/'originals/firearm';out.mkdir(parents=True,exist_ok=True);archive.seek(0);proc=subprocess.run(['bsdtar','-x','-f',f'/dev/fd/{archive.fileno()}','-C',str(out),'--']+selected,pass_fds=(archive.fileno(),),capture_output=True);print(proc.stderr.decode()[:1200]);proc.check_returncode();archive.close()
(R/'records/firearm_download.json').write_text(json.dumps({'page':page,'url':url,'author':'Ben Jaszczak; Brian Nelson; Kevin Heras; Matthew Nanney','license':'CC0-1.0','archive_sha256':hashlib.sha256(data).hexdigest(),'archive_saved':False,'selected_files':selected},indent=2));print('Extracted',sum(n.lower().endswith('.wav') for n in selected),'original WAV files plus description CSV',flush=True)
